import React, { useState, useEffect, useCallback } from 'react';
import { useSearchParams, useNavigate } from 'react-router-dom';
import PropertyCard from '../components/PropertyCard';
import EnquiryModal from '../components/EnquiryModal';
import { getProperties, getFilters } from '../services/api';
import { SlidersHorizontal, ChevronDown, X } from 'lucide-react';
import styles from './SearchResultsPage.module.css';

export default function SearchResultsPage() {
  const [searchParams, setSearchParams] = useSearchParams();
  const navigate = useNavigate();

  const [properties, setProperties]   = useState([]);
  const [loading,    setLoading]       = useState(true);
  const [total,      setTotal]         = useState(0);
  const [page,       setPage]          = useState(1);
  const [filters,    setFilters]       = useState({ propertyTypes: [], budgetRanges: [] });
  const [enquiryProp, setEnquiryProp] = useState(null);
  const [showFilters, setShowFilters] = useState(false);

  // Read params
  const city         = searchParams.get('city')         || '';
  const listingType  = searchParams.get('listingType')  || '';
  const propertyType = searchParams.get('propertyType') || '';
  const budget       = searchParams.get('budget')       || '';
  const buildingType = searchParams.get('buildingType') || '';

  useEffect(() => {
    getFilters().then(({ data }) => setFilters(data)).catch(() => {});
  }, []);

  const fetchProperties = useCallback(() => {
    setLoading(true);
    const params = { page, limit: 12 };
    if (city)         params.city         = city;
    if (listingType)  params.listingType  = listingType;
    if (propertyType) params.propertyType = propertyType;
    if (buildingType) params.buildingType = buildingType;
    if (budget) {
      const [min, max] = budget.split('-');
      if (min) params.minPrice = min;
      if (max) params.maxPrice = max;
    }
    getProperties(params)
      .then(({ data }) => { setProperties(data.properties || []); setTotal(data.total || 0); })
      .catch(() => setProperties([]))
      .finally(() => setLoading(false));
  }, [city, listingType, propertyType, budget, buildingType, page]);

  useEffect(() => { fetchProperties(); }, [fetchProperties]);

  const setParam = (key, value) => {
    const next = new URLSearchParams(searchParams);
    if (value) next.set(key, value); else next.delete(key);
    setPage(1);
    setSearchParams(next);
  };

  const clearAll = () => { setSearchParams({}); setPage(1); };

  const activeFilters = [city, listingType, propertyType, budget, buildingType].filter(Boolean);

  return (
    <div className={styles.wrap}>
      <div className={`container ${styles.inner}`}>
        {/* Sidebar */}
        <aside className={`${styles.sidebar} ${showFilters ? styles.sidebarOpen : ''}`}>
          <div className={styles.sidebarHeader}>
            <span className={styles.sidebarTitle}>Filters</span>
            {activeFilters.length > 0 && (
              <button className={styles.clearBtn} onClick={clearAll}>Clear All</button>
            )}
          </div>

          <div className={styles.filterGroup}>
            <div className={styles.filterLabel}>Listing Type</div>
            {[{ id: 'Sell', label: 'Buy' }, { id: 'Rent', label: 'Rent' }].map(t => (
              <label key={t.id} className={styles.filterOption}>
                <input
                  type="radio" name="listingType"
                  checked={listingType === t.id}
                  onChange={() => setParam('listingType', listingType === t.id ? '' : t.id)}
                />
                {t.label}
              </label>
            ))}
          </div>

          <div className={styles.filterGroup}>
            <div className={styles.filterLabel}>Property Type</div>
            {filters.propertyTypes.map(t => (
              <label key={t.id} className={styles.filterOption}>
                <input
                  type="checkbox"
                  checked={propertyType === t.id}
                  onChange={() => setParam('propertyType', propertyType === t.id ? '' : t.id)}
                />
                {t.label}
              </label>
            ))}
          </div>

          <div className={styles.filterGroup}>
            <div className={styles.filterLabel}>Budget</div>
            {filters.budgetRanges.map(b => (
              <label key={b.id} className={styles.filterOption}>
                <input
                  type="radio" name="budget"
                  checked={budget === b.id}
                  onChange={() => setParam('budget', budget === b.id ? '' : b.id)}
                />
                {b.label}
              </label>
            ))}
          </div>
        </aside>

        {/* Main */}
        <main className={styles.main}>
          <div className={styles.topBar}>
            <div>
              <h1 className={styles.heading}>
                {city ? `Properties in ${city}` : 'All Properties'}
              </h1>
              {!loading && <p className={styles.count}>{total} {total === 1 ? 'result' : 'results'} found</p>}
            </div>
            <button className={styles.filterToggle} onClick={() => setShowFilters(o => !o)}>
              <SlidersHorizontal size={16} />
              Filters {activeFilters.length > 0 && `(${activeFilters.length})`}
            </button>
          </div>

          {/* Active filter chips */}
          {activeFilters.length > 0 && (
            <div className={styles.chips}>
              {city         && <span className={styles.chip}>{city}         <button onClick={() => setParam('city', '')}>×</button></span>}
              {listingType  && <span className={styles.chip}>{listingType === 'Sell' ? 'Buy' : 'Rent'} <button onClick={() => setParam('listingType', '')}>×</button></span>}
              {propertyType && <span className={styles.chip}>{propertyType} <button onClick={() => setParam('propertyType', '')}>×</button></span>}
              {budget       && <span className={styles.chip}>Budget set   <button onClick={() => setParam('budget', '')}>×</button></span>}
              {buildingType && <span className={styles.chip}>{buildingType} <button onClick={() => setParam('buildingType', '')}>×</button></span>}
            </div>
          )}

          {loading ? (
            <div className={styles.loading}>Searching properties…</div>
          ) : properties.length === 0 ? (
            <div className={styles.empty}>
              <div style={{ fontSize: 48 }}>🔍</div>
              <div className={styles.emptyTitle}>No properties found</div>
              <div className={styles.emptySub}>Try adjusting your filters</div>
              <button className={styles.clearBtn2} onClick={clearAll}>Clear Filters</button>
            </div>
          ) : (
            <div className={styles.grid}>
              {properties.map(p => (
                <PropertyCard key={p.id || p._id} property={p} onEnquire={setEnquiryProp} />
              ))}
            </div>
          )}

          {/* Pagination */}
          {total > 12 && (
            <div className={styles.pagination}>
              <button disabled={page <= 1} onClick={() => setPage(p => p - 1)} className={styles.pageBtn}>← Prev</button>
              <span className={styles.pageInfo}>Page {page}</span>
              <button disabled={properties.length < 12} onClick={() => setPage(p => p + 1)} className={styles.pageBtn}>Next →</button>
            </div>
          )}
        </main>
      </div>

      {enquiryProp && <EnquiryModal property={enquiryProp} onClose={() => setEnquiryProp(null)} />}
    </div>
  );
}
